
fn seeded(n:u64)->sha3::Shake256Reader{let mut h=Shake256::default();h.update(b"local-mr-macro-proof-v1");h.update(&n.to_le_bytes());h.finalize_xof()}
fn main(){let args:Vec<_>=std::env::args().collect();let all=load_ops(&args[1]).unwrap();let(nq,nb,_,_)=analyze_ops(all.iter());let start:usize=args[2].parse().unwrap();let end:usize=args[3].parse().unwrap();let mode=&args[4];assert!(mode=="arbitrary"||mode=="zero_reset");let ops=&all[start..=end];let mut used=std::collections::BTreeSet::new();let mut resets=std::collections::BTreeSet::new();let mut cbits=std::collections::BTreeSet::new();for o in ops{use OperationType::*;if matches!(o.kind,X|CX|CCX|Swap|R|Hmr){used.insert(o.q_target.0 as usize);}if matches!(o.kind,CX|CCX|Swap){used.insert(o.q_control1.0 as usize);}if o.kind==CCX{used.insert(o.q_control2.0 as usize);}if matches!(o.kind,R|Hmr){resets.insert(o.q_target.0 as usize);}if o.c_condition.0!=u64::MAX{cbits.insert(o.c_condition.0 as usize);}if o.kind==Hmr{cbits.insert(o.c_target.0 as usize);}}
 let mut alg=GlobalAnf::new(32);let mut q=vec![GlobalAnf::constant(0);nq as usize];let mut b=vec![GlobalAnf::constant(0);nb as usize];let mut inputs=Vec::new();for wire in &used{if mode=="zero_reset"&&resets.contains(wire){continue;}let id=alg.dag.variable(false);q[*wire]=GlobalAnf::constant(id);inputs.push((id,*wire));}for id in &cbits{b[*id]=alg.fresh();}let initial=q.clone();let initialb=b.clone();let mut base=GlobalAnf::constant(1);let mut active=GlobalAnf::constant(1);let mut stack=Vec::new();let timer=std::time::Instant::now();let mut mr=0;
 for o in ops{use OperationType::*;if matches!(o.kind,Neg|Z|CZ|CCZ|Register|AppendToRegister|DebugPrint){continue;}if o.kind==PopCondition{base=stack.pop().unwrap();continue;}let c=if o.c_condition.0==u64::MAX{base.clone()}else{alg.and(&base,&b[o.c_condition.0 as usize])};let t=o.q_target.0 as usize;let bt=o.c_target.0 as usize;match o.kind{CCX=>{let v=alg.and(&q[o.q_control1.0 as usize],&q[o.q_control2.0 as usize]);let v=alg.and(&v,&c);q[t]=alg.xor(&q[t],&v);},CX=>{let v=alg.and(&q[o.q_control1.0 as usize],&c);q[t]=alg.xor(&q[t],&v);},X=>q[t]=alg.xor(&q[t],&c),Swap=>{let a=o.q_control1.0 as usize;let v=alg.xor(&q[t],&q[a]);let v=alg.and(&v,&c);q[t]=alg.xor(&q[t],&v);q[a]=alg.xor(&q[a],&v);},R|Hmr=>{mr+=1;let random=alg.fresh();let nc=alg.not(&c);q[t]=alg.and(&q[t],&nc);if o.kind==Hmr{let old=alg.and(&b[bt],&nc);let new=alg.and(&random,&c);b[bt]=alg.xor(&old,&new);}},BitStore0=>{let nc=alg.not(&c);b[bt]=alg.and(&b[bt],&nc);},BitStore1=>{let nc=alg.not(&c);let old=alg.and(&b[bt],&nc);b[bt]=alg.xor(&old,&c);},BitInvert=>b[bt]=alg.xor(&b[bt],&c),PushCondition=>{stack.push(base);base=c.clone();active=c;},_=>unreachable!()}}
 assert!(stack.is_empty());let mut identity=Vec::new();let mut conditional_reset=Vec::new();let mut unresolved=Vec::new();let nc=alg.not(&active);for wire in &used{let difference=alg.xor(&q[*wire],&initial[*wire]);if difference.0.iter().all(|(_,c)|alg.dag.find(*c)==0){identity.push(*wire);continue;}let expected=alg.and(&initial[*wire],&nc);let difference=alg.xor(&q[*wire],&expected);if resets.contains(wire)&&difference.0.iter().all(|(_,c)|alg.dag.find(*c)==0){conditional_reset.push(*wire);}else{unresolved.push(*wire);}}
 let mut sample_changes=std::collections::BTreeSet::new();let mut sample_data_changes=std::collections::BTreeSet::new();for sample in 0..4{let mut input_random=seeded(100+sample);let mut iq=vec![0;nq as usize];for(_,wire)in &inputs{let mut raw=[0;8];XofReader::read(&mut input_random,&mut raw);iq[*wire]=u64::from_le_bytes(raw);}let mut values=vec![0u64;alg.dag.nodes.len()];values[1]=u64::MAX;for(id,wire)in &inputs{values[*id as usize]=iq[*wire];}for(i,n)in alg.dag.nodes.iter().enumerate().skip(2){assert!(!n.random);match n.kind{2=>{},3=>values[i]=values[n.a as usize]^values[n.b as usize],4=>values[i]=values[n.a as usize]&values[n.b as usize],7=>values[i]=alg.dag.large_defs[n.a as usize].iter().fold(0,|a,m|a^alg.dag.monomials[*m as usize].iter().fold(u64::MAX,|a,j|a&values[*j as usize])),8=>values[i]=[n.a,n.b].iter().fold(u64::MAX,|a,m|a&alg.dag.monomials[*m as usize].iter().fold(u64::MAX,|a,j|a&values[*j as usize])),_=>panic!()}}
 let concrete=|p:&GlobalPoly|{let(mut c,mut d)=(0,0);for(k,v)in &p.0{if k.is_empty(){c^=values[*v as usize]}else{d|=values[*v as usize]}}(c,!d)};for seed in 0..4{let mut random=seeded(seed);let mut ib=vec![0;nb as usize];for bit in &cbits{let mut raw=[0;8];XofReader::read(&mut random,&mut raw);ib[*bit]=u64::from_le_bytes(raw);}let mut sim=Simulator::new(nq as usize,nb as usize,&mut random);sim.qubits.copy_from_slice(&iq);sim.bits.copy_from_slice(&ib);sim.apply_iter(ops.iter());for wire in &used{let(c,k)=concrete(&q[*wire]);assert_eq!((sim.qubits[*wire]^c)&k,0,"quantum containment wire{wire}");if sim.qubits[*wire]!=iq[*wire]{sample_changes.insert(*wire);if !resets.contains(wire){sample_data_changes.insert(*wire);}}}for bit in &cbits{let(c,k)=concrete(&b[*bit]);assert_eq!((sim.bits[*bit]^c)&k,0,"classical containment bit{bit}");}for wire in &identity{assert_eq!(sim.qubits[*wire],iq[*wire]);}}}
 let report=serde_json::json!({"source_stream":args[1],"start_inclusive":start,"end_inclusive":end,"operation_count":ops.len(),"initial_assumption":mode,"arbitrary_input_qubits":inputs.len(),"known_zero_initial_qubits":if mode=="zero_reset"{resets.iter().copied().collect::<Vec<_>>()}else{Vec::new()},"initial_classical_bits_arbitrary_including_outer_measurements":cbits,"used_quantum_wires":used,"reset_target_qubits":resets,"proved_identity_wires":identity,"proved_conditional_reset_wires":conditional_reset,"unresolved_wires":unresolved,"proved_complete_value_identity":identity.len()==used.len(),"input_only_coefficient_nodes":alg.dag.nodes.len(),"outer_rng_caps":alg.capped,"mr_events":mr,"fresh_symbols":alg.next,"sample_changes":sample_changes,"sample_nonreset_data_changes":sample_data_changes,"protected_cases":1024,"seconds":timer.elapsed().as_secs_f64(),"status":"LOCAL_PROOF_WITH_EXPLICIT_ASSUMPTIONS_NOT_GLOBAL_CERTIFICATE"});println!("{report}");let _=initialb;}
